-- Migration 0006 — the loader run record (plan step M4.8).
--
-- One row per runner invocation and one row per loader or
-- canary probe inside it, written by the runner only — never by
-- the loaders themselves, so no loader can fail because logging
-- failed. The alert belongs to the run: its status and error are
-- recorded here, never swallowed. A run left in 'running' with
-- no finish time is itself evidence of a killed run.
--
-- The run id is a UUID generated by the runner; no extension is
-- needed. Volume is a handful of rows a month; keep them forever.

CREATE TABLE loader_runs (
  id uuid PRIMARY KEY,
  kind text NOT NULL,
  environment text NOT NULL,
  trigger_source text NOT NULL,
  status text NOT NULL DEFAULT 'running',
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  alert_status text NOT NULL DEFAULT 'not_required',
  alert_sent_at timestamptz,
  alert_error text,
  summary text
);

CREATE TABLE loader_run_items (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  run_id uuid NOT NULL REFERENCES loader_runs (id),
  item text NOT NULL,
  mode text NOT NULL,
  status text NOT NULL,
  started_at timestamptz,
  finished_at timestamptz,
  duration_ms integer,
  source_name text,
  source_date date,
  log_line text,
  error_message text,
  exit_code integer
);
CREATE INDEX loader_run_items_run_idx ON loader_run_items (run_id);
